/* Google Drive shared-space sync. The admin owns one Drive folder ("공유공간") shared with members.
   Every change is an immutable journal file in that folder; Drive records who uploaded each file,
   and journal.materialize() uses that to ignore changes a member is not allowed to make.
   Access tokens exist only in memory. */
(function(){
'use strict';
const C=window.PMS,J=window.MoaJournal,CONFIG='moa.drive.config.v1',ACTIVE='cal.space.active.v2',SCOPE='https://www.googleapis.com/auth/drive',FOLDER='application/vnd.google-apps.folder';
let config={...(window.MOA_DRIVE_CONFIG||{})},account=null,cache=null,token='',expires=0,client=null,busy=false,again=false,status='Google 미연결',lastSync='',hooks=null,authLoading=null,paused=false,writable=!navigator.locks;
const uid=()=>crypto.randomUUID();
const admin=()=>(config.adminEmail||'').toLowerCase();
try{if(!config.clientId)config={...config,...JSON.parse(localStorage.getItem(CONFIG)||'{}')};account=JSON.parse(localStorage.getItem(ACTIVE)||'null');if(account&&account.clientId!==config.clientId)account=null;if(account){cache=JSON.parse(localStorage.getItem(account.key));if(cache){cache.ops=J.merge([],cache.ops);C.validate(J.materialize(cache.ops,admin()));status='Google 재연결 필요';}else account=null;}}catch(_){account=null;cache=null;status='동기화 캐시 확인 필요';paused=true;}
function emit(message){if(message)status=message;hooks?.status(status);}
function persist(next){localStorage.setItem(account.key,JSON.stringify(next));cache=next;}
function current(){return C.validate(J.materialize(cache.ops,admin()));}
function save(next,previous){if(!writable)throw Error('다른 캘린더 탭을 닫고 이 탭을 새로고침해주세요.');if(!account||!cache||!cache.space)throw Error('공유 공간에 연결된 뒤 저장할 수 있습니다.');if(paused)throw Error('동기화 캐시를 먼저 확인해주세요.');const changes=J.diff(previous,next);if(!changes.length)return;const op={version:1,id:uid(),device:cache.device,clock:Math.max(0,...cache.ops.map(x=>x.clock))+1,createdAt:new Date().toISOString(),changes,author:account.email};persist({...cache,ops:J.merge(cache.ops,[op]),pending:[...cache.pending,op.id]});emit(navigator.onLine?'Drive 저장 대기':'오프라인 · 변경 보관 중');schedule();}
function initial(fallback){return account&&cache?current():fallback;}
function schedule(){if(token&&account){if(busy){again=true;return;}queueMicrotask(sync);}}
function fresh(){if(!token||Date.now()>=expires){token='';throw Error('Google 재연결 필요');}}
async function request(path,options={}){fresh();const r=await fetch('https://www.googleapis.com/'+path,{...options,headers:{Authorization:'Bearer '+token,...options.headers},signal:AbortSignal.timeout(options.timeout||30000)});if(r.status===401){token='';throw Error('Google 재연결 필요');}if(!r.ok){const body=await r.json().catch(()=>({}));throw Error(r.status===403?'Drive 권한을 확인해주세요. (공유 공간 초대 여부, API 설정)':r.status===404?'공유 공간 파일을 찾을 수 없습니다.':r.status===429?'요청이 많아 잠시 후 다시 시도합니다.':body.error?.message||'Drive 연결 오류 ('+r.status+')');}return r;}
async function api(path,options){const r=await request(path,options);return r.status===204?{}:r.json();}
const q=s=>"'"+s.replace(/\\/g,'\\\\').replace(/'/g,"\\'")+"'";
async function list(query,fields){let pageToken='',files=[];do{const params=new URLSearchParams({q:query,pageSize:'1000',fields:'nextPageToken,files('+fields+')',includeItemsFromAllDrives:'true',supportsAllDrives:'true'});if(pageToken)params.set('pageToken',pageToken);const page=await api('drive/v3/files?'+params);files.push(...(page.files||[]));pageToken=page.nextPageToken||'';}while(pageToken);return files;}
// Find the admin's shared folder; the admin creates it on first sign-in.
async function findSpace(){const folders=await list("mimeType='"+FOLDER+"' and properties has { key='calendarSpace' and value='1' } and trashed=false",'id,owners(emailAddress)');const own=folders.find(f=>(f.owners||[]).some(o=>(o.emailAddress||'').toLowerCase()===admin()));if(own)return own.id;if(account.email!==admin())return '';const made=await api('drive/v3/files?fields=id',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:'나의 캘린더 공유공간',mimeType:FOLDER,properties:{calendarSpace:'1'}})});return made.id;}
async function pull(){let known=new Set(cache.seen||[]),remote=[],seen=[];const files=await list(q(cache.space)+" in parents and properties has { key='calJournal' and value='1' } and trashed=false",'id,size,owners(emailAddress)');
 for(const f of files){if(!known.has(f.id)){if(Number(f.size)>8*1024*1024){seen.push(f.id);continue;}try{const op=J.check(await api('drive/v3/files/'+encodeURIComponent(f.id)+'?alt=media'));op.author=((f.owners||[])[0]?.emailAddress||'').toLowerCase();J.merge(cache.ops,[op]);remote.push(op);}catch(e){if(/재연결|요청이 많아/.test(e.message))throw e;/* malformed or conflicting file: skip it */}}seen.push(f.id);}
 // Read the latest local cache after network awaits, preserving edits made in flight.
 let ops=cache.ops;for(const op of remote){try{ops=J.merge(ops,[op]);}catch(_){}}C.validate(J.materialize(ops,admin()));const remoteIds=new Set(remote.map(x=>x.id));persist({...cache,ops,seen:[...new Set([...(cache.seen||[]),...seen])],pending:cache.pending.filter(id=>!remoteIds.has(id))});hooks.replace(current());}
function multipart(meta,blob,type){const boundary='cal_'+uid().replace(/-/g,'');return {headers:{'Content-Type':'multipart/related; boundary='+boundary},body:new Blob(['--'+boundary+'\r\nContent-Type: application/json; charset=UTF-8\r\n\r\n'+JSON.stringify(meta)+'\r\n--'+boundary+'\r\nContent-Type: '+(type||'application/octet-stream')+'\r\n\r\n',blob,'\r\n--'+boundary+'--'])};}
async function upload(op){const {author,...body}=op;const m=multipart({name:'calendar-change-'+op.id+'.json',mimeType:'application/json',parents:[cache.space],properties:{calJournal:'1'}},JSON.stringify(body),'application/json');return api('upload/drive/v3/files?uploadType=multipart&fields=id',{method:'POST',...m});}
async function sync(){if(busy){again=true;return;}if(!account||!cache||paused||!writable)return;if(!navigator.onLine){emit('오프라인 · 변경 보관 중');return;}if(!token||Date.now()>=expires){emit('Google 재연결 필요');return;}busy=true;try{emit('Drive 동기화 중');
 if(!cache.space){const space=await findSpace();if(!space){emit('관리자의 초대를 기다리는 중입니다.');hooks.space?.();return;}persist({...cache,space});hooks.space?.();}
 await pull();for(const id of [...cache.pending]){const op=cache.ops.find(x=>x.id===id);if(!op)throw Error('대기 중인 변경 기록을 확인해주세요.');const file=await upload(op);persist({...cache,pending:cache.pending.filter(x=>x!==id),seen:[...new Set([...(cache.seen||[]),file.id])]});}await pull();lastSync=new Date().toLocaleTimeString('ko-KR',{hour:'2-digit',minute:'2-digit'});emit(cache.pending.length?'Drive 저장 대기':'Drive 동기화 완료 · '+lastSync);}catch(e){emit(e.message||'동기화 실패 · 변경은 기기에 보관');}finally{busy=false;if(again){again=false;schedule();}}}
// Photos and files for the board live next to the journal in the shared folder.
async function uploadFile(blob,name,type){if(!cache?.space)throw Error('공유 공간에 먼저 연결해주세요.');const m=multipart({name,mimeType:type||'application/octet-stream',parents:[cache.space],properties:{calMedia:'1'}},blob,type);return (await api('upload/drive/v3/files?uploadType=multipart&fields=id',{method:'POST',timeout:120000,...m})).id;}
async function media(id){const r=await request('drive/v3/files/'+encodeURIComponent(id)+'?alt=media',{timeout:120000});return r.blob();}
async function trash(id){await api('drive/v3/files/'+encodeURIComponent(id)+'?fields=id',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({trashed:true})});}
async function share(email){if(!cache?.space)throw Error('공유 공간이 아직 없습니다.');await api('drive/v3/files/'+encodeURIComponent(cache.space)+'/permissions?sendNotificationEmail=true&fields=id',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({type:'user',role:'writer',emailAddress:email})});}
async function unshare(email){if(!cache?.space)return;const r=await api('drive/v3/files/'+encodeURIComponent(cache.space)+'/permissions?fields=permissions(id,emailAddress)');for(const p of r.permissions||[])if((p.emailAddress||'').toLowerCase()===email)await api('drive/v3/files/'+encodeURIComponent(cache.space)+'/permissions/'+encodeURIComponent(p.id),{method:'DELETE'});}
function loadGIS(){if(window.google?.accounts?.oauth2)return Promise.resolve();if(authLoading)return authLoading;authLoading=new Promise((resolve,reject)=>{const s=document.createElement('script');s.src='https://accounts.google.com/gsi/client';s.async=true;s.onload=()=>resolve();s.onerror=()=>{authLoading=null;s.remove();reject(Error('Google 로그인 모듈을 불러오지 못했습니다.'));};document.head.append(s);});return authLoading;}
async function ready(){if(!config.clientId)return;await loadGIS();client=google.accounts.oauth2.initTokenClient({client_id:config.clientId,scope:SCOPE,include_granted_scopes:false,callback:authorized,error_callback:()=>emit('로그인 창이 닫혔습니다. 다시 로그인해주세요.')});}
async function authorized(response){if(response.error){emit('Google 연결을 허용하지 않았습니다.');return;}if(!google.accounts.oauth2.hasGrantedAllScopes(response,SCOPE)){emit('Google Drive 권한에 체크한 뒤 다시 로그인해주세요.');return;}token=response.access_token;expires=Date.now()+Number(response.expires_in)*1000-60000;try{const about=await api('drive/v3/about?fields=user(emailAddress,displayName)');const email=(about.user?.emailAddress||'').toLowerCase();if(!email)throw Error('Google 계정을 확인하지 못했습니다.');const nextAccount={email,name:about.user.displayName||email.split('@')[0],clientId:config.clientId,key:'cal.space.cache.v2:'+config.clientId+':'+email};let nextCache=JSON.parse(localStorage.getItem(nextAccount.key)||'null');if(!nextCache)nextCache={version:2,device:uid(),ops:[],pending:[],seen:[],space:''};nextCache.ops=J.merge([],nextCache.ops);localStorage.setItem(ACTIVE,JSON.stringify(nextAccount));account=nextAccount;cache=nextCache;persist(cache);paused=false;hooks.replace(current());hooks.account?.();emit('Google 연결됨');await sync();}catch(e){token='';emit(e.message);}}
function connect(){if(!writable){emit('다른 캘린더 탭을 닫고 새로고침해주세요.');return;}if(!config.clientId){emit('OAuth 클라이언트 ID 설정이 필요합니다.');return;}if(!client){emit('로그인 모듈 준비 중 · 잠시 후 다시 눌러주세요.');ready().catch(e=>emit(e.message));return;}if(busy){emit('동기화가 끝난 뒤 다시 시도해주세요.');return;}client.requestAccessToken({prompt:account?'':'select_account'});}
function disconnect(){if(!writable)throw Error('다른 캘린더 탭에서 연결을 관리해주세요.');if(busy)throw Error('동기화가 끝난 뒤 로그아웃해주세요.');localStorage.removeItem(ACTIVE);token='';expires=0;account=null;cache=null;hooks.replace(C.blank());emit('Google 미연결');}
// Data saved by the earlier single-user version (browser storage and the old per-user Drive cache).
function legacy(){const out=C.blank();const add=d=>{for(const k of ['projects','tasks','events'])for(const x of d[k]||[])if(!out[k].some(y=>y.id===x.id))out[k].push(x);};try{const local=localStorage.getItem('moa.personal-pms.v1');if(local)add(C.normalize(JSON.parse(local)));}catch(_){}for(let i=0;i<localStorage.length;i++){const k=localStorage.key(i);if(k&&k.startsWith('moa.drive.cache.v1:'))try{add(J.materialize(JSON.parse(localStorage.getItem(k)).ops));}catch(_){}}return out;}
window.MoaDrive={init(h){hooks=h;if(navigator.locks)navigator.locks.request('moa-drive-writer',{ifAvailable:true},async lock=>{writable=!!lock;if(!lock){emit('다른 캘린더 탭 사용 중 · 이 탭은 읽기 전용');return;}await new Promise(()=>{});}).catch(()=>emit('저장 권한 확인 실패 · 새로고침 필요'));emit();if(config.clientId)ready().catch(e=>emit(e.message));},initial,save,sync,connect,disconnect,legacy,uploadFile,media,trash,share,unshare,info:()=>({status,clientId:config.clientId||'',admin:admin(),account:account?.email||'',name:account?.name||'',isAdmin:!!account&&account.email===admin(),space:cache?.space||'',pending:cache?.pending.length||0,connected:!!token&&Date.now()<expires,lastSync})};
window.addEventListener('online',schedule);window.addEventListener('focus',()=>{if(!document.hidden)schedule();});document.addEventListener('visibilitychange',()=>{if(!document.hidden)schedule();});setInterval(()=>{if(!document.hidden)schedule();},30000);
// Another tab can edit the same account cache. Reload it before syncing/rendering.
window.addEventListener('storage',e=>{if(account&&e.key===account.key&&e.newValue){try{const incoming=JSON.parse(e.newValue);incoming.ops=J.merge([],incoming.ops);cache=incoming;hooks?.replace(current());schedule();}catch(_){paused=true;emit('다른 탭의 동기화 데이터를 확인해주세요.');}}if(e.key===ACTIVE&&e.newValue!==JSON.stringify(account)){token='';paused=true;emit('다른 탭에서 계정 변경 · 새로고침 필요');}});
})();
